from collections import defaultdict

def has_cycle_dfs(n, edges):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
    state = [0] * n  # 0 unseen, 1 active, 2 done

    def dfs(u):
        state[u] = 1
        for v in g[u]:
            if state[v] == 1:
                return True
            if state[v] == 0 and dfs(v):
                return True
        state[u] = 2
        return False

    for u in range(n):
        if state[u] == 0 and dfs(u):
            return True
    return False

