#include <bits/stdc++.h>
using namespace std;

bool hasCycleKahn(int n, vector<pair<int,int>> edges) {
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0);
    for (auto [u, v] : edges) {
        g[u].push_back(v);
        indeg[v]++;
    }
    queue<int> q;
    for (int i = 0; i < n; i++) if (indeg[i] == 0) q.push(i);
    int taken = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        taken++;
        for (int v : g[u]) if (--indeg[v] == 0) q.push(v);
    }
    return taken != n;
}
